<?php
declare(strict_types=1);
namespace App\Controllers;use App\Core\{Csrf,Request,Response,View};use App\Security\Auth;use App\Services\GeneralSettingsService;use Throwable;
final readonly class SettingsController{public function __construct(private View $view,private GeneralSettingsService $service,private Csrf $csrf){}public function index(Request $r):void{$this->allow();$tab=$r->string('tab')?:'general';$defs=$this->service->definitions();if(!isset($defs[$tab]))$tab='general';$this->view->render('settings/index',['title'=>'Ajustes generales','definitions'=>$defs,'values'=>$this->service->values(),'tab'=>$tab,'csrf'=>$this->csrf]);}public function save(Request $r):void{$this->allow();$tab=$r->string('tab');try{$this->service->save($tab,$r->input);Response::redirect('/settings?tab='.rawurlencode($tab));}catch(Throwable $e){http_response_code(422);exit(htmlspecialchars($e->getMessage(),ENT_QUOTES,'UTF-8'));}}private function allow():void{if(!Auth::can('settings.manage')){http_response_code(403);exit('Sin permiso');}}}
